import type { ResearchPost } from './fleet-data';

export const novemberSevenResearchBatch: readonly ResearchPost[] = [{"slug":"developeroffshore-what-a-two-week-offshore-pilot-can-prove","title":"What a two-week offshore developer pilot can and cannot prove","excerpt":"A bounded analysis of short offshore developer pilots: which delivery claims a two-week sample can support, where selection and review bias enter, and how to write a defensible exit decision.","published":"2026-11-07","updated":"2026-11-07","sections":[{"heading":"Question and scope","body":["This analysis asks what a two-week offshore developer pilot can support when a buyer team must decide whether to continue an assignment. The unit is one pilot with a named decision, a small ticket set, a reviewer, and an evidence record. The observation window begins when access is granted and ends at the exit review. Claims about long-term performance, retention, or team fit sit outside the sample unless the pilot produced direct evidence for them.","The pilot is not a controlled experiment, and it should not be described as one. The developer knows the work is being observed, the ticket set is small, and the reviewer may be the same person who selected the candidate. Those conditions can still produce useful evidence about a bounded workflow. The report therefore separates what the record shows from what the buyer hopes the record implies."]},{"heading":"What a short sample can support","body":["A two-week pilot can show whether one developer can start in the actual repository, follow the review path, and finish a small change with usable evidence. It can also show whether the buyer team can provide tickets, access, and decisions at the pace the work requires. Both findings matter because a failed pilot may describe the environment rather than the developer. The record should name which side of that boundary failed.","The sample can support a decision about the next bounded step, such as adding one responsibility or extending the assignment for a month. It cannot establish a stable delivery rate across different work, because two weeks rarely include enough variety. A cautious conclusion is still useful when the evidence is specific. The buyer can act on a narrow finding without pretending it answers every future question."]},{"heading":"Selection effects in a short pilot","body":["The tickets chosen for a pilot are rarely a random sample of the backlog. Teams tend to pick work that is important enough to observe and safe enough to share, which may be easier or harder than normal delivery. The reviewer may also give more attention because the pilot is visible. Record how the tickets were selected and who reviewed them so a later reader can judge the comparison.","A developer who has just joined also benefits from concentrated setup help that will not continue at the same level. That support is reasonable, but it limits claims about independent operation. Note the amount of buyer-side help provided during the pilot, including pairing time and decision turnaround. A pilot completed with daily coaching says something different from one completed with ordinary support."]},{"heading":"Evidence quality and reviewer independence","body":["The strongest pilot evidence is a finished change linked to its ticket, its acceptance check, and a reviewer decision. A merged pull request alone is weak if nobody recorded what was tested or what remained uncertain. Ask the reviewer to distinguish a change that passed the agreed checks from one that was accepted with an exception. That distinction is often more useful than a general impression of quality.","Reviewer independence matters because the person who chose the candidate may want the pilot to succeed. Use a second reviewer for at least one ticket when the team has that capacity. If a second reviewer is unavailable, record the conflict and treat the finding as provisional. Independence does not guarantee a correct decision, but it makes an obvious bias visible in the record."]},{"heading":"Activity metrics and the wrong denominator","body":["Commit counts, message volume, and online hours are easy to collect and poor proxies for finished work. A developer may commit many small changes while exploring, or one large change that takes longer to review. Neither pattern tells the buyer whether the work is correct or safe. Use activity data only to understand the workflow, never as a score for the person.","The better denominator is the set of tickets the pilot intended to finish. Report how many were completed, how many returned for rework, and how many waited on a buyer decision. A completion rate without the eligible set can be inflated by dropping difficult work. Keep the original scope visible so the exit review cannot quietly redefine success."]},{"heading":"Access and record boundaries","body":["Pilot records should contain the minimum identity and customer information needed to judge the work. Use synthetic data where possible and keep access logs with the approval that justified each permission. Do not place raw production records in a retrospective document just because they make the story concrete. The evidence standard should protect customers while still allowing a reviewer to repeat the check.","Record the environment, the repository revision, and the date of each observation so a later reader can tell what changed. Separate missing evidence from a confirmed negative result, because an unchecked field is not proof that a problem does not exist. Remove temporary access at the end of the pilot and record the removal. Those housekeeping facts are part of the decision record, not an afterthought."]},{"heading":"How buyer-side behavior enters the record","body":["The buyer team controls tickets, access, and decisions, so its behavior is part of the pilot evidence. Record how quickly a question received an answer and whether the answer arrived with enough context to act. A developer who waits two days for a simple decision is not working in the same conditions as one who receives an answer the same morning. The difference belongs in the record even when it is uncomfortable for the buyer.","Also record the amount of rework caused by a changed requirement rather than by a coding mistake. A pilot can look weak when the target moved after the first review. The reviewer should label the cause and the date of the change, then judge the developer against the requirement that was actually in force. Fair evidence separates the work from the environment around it."]},{"heading":"Reporting the result to a decision maker","body":["A useful pilot report is short enough to read before the exit meeting and specific enough to support a decision. Start with the decision question, then state the outcome and the evidence behind it. Include the tickets, the review results, the buyer-side blockers, and the remaining uncertainty. End with the next owner and the date of the next check.","Do not bury a failed check inside a positive narrative or average it away with a strong ticket. A decision maker needs the adverse case as much as the success. Write the report in plain language and avoid turning a two-week sample into a claim about a person's character. The report should make the next step obvious without pretending the evidence is stronger than it is."]},{"heading":"Limits of the conclusion","body":["Two weeks cannot show how a developer handles a production incident, a difficult stakeholder, or a major architecture disagreement. It cannot prove retention, long-term quality, or the cost of replacing someone later. The report should state those limits plainly and avoid turning a short observation into a broad prediction. A decision to continue is a bet on the next stage, not a guarantee.","The result also depends on the buyer team's own performance during the pilot. Late decisions, missing tickets, and slow reviews can make a capable developer look ineffective. Include those conditions in the record and distinguish them from the developer's output. A pilot that fails for environmental reasons should lead to a process fix, not automatically to a replacement."]},{"heading":"A decision rule for the exit review","body":["Write the decision rule before the pilot begins and read it again at the exit meeting. A pass should require completed work, acceptable review evidence, and a record of how blockers were handled. A conditional pass should name the specific gap, the support that will address it, and the date of the next review. A stop should state which condition failed and what access or work must be closed.","The meeting should end with one recorded outcome and one next owner. Do not average a strong ticket against a serious review failure and call the result acceptable. Do not let a single easy ticket outweigh repeated missing evidence either. The rule exists to keep the decision consistent when the people in the room remember different parts of the pilot."]}],"sources":[{"name":"U.S. Bureau of Labor Statistics, Software Developers","url":"https://www.bls.gov/ooh/computer-and-information-technology/software-developers.htm"},{"name":"NIST SP 800-53 Rev. 5, Security and Privacy Controls","url":"https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"},{"name":"CISA Zero Trust Maturity Model","url":"https://www.cisa.gov/zero-trust-maturity-model"}],"keyStats":["1 named decision per pilot","2 weeks of observation, not a performance forecast","3 exit outcomes: pass, conditional pass, stop","4 evidence states: complete, missing, restricted, confirmed negative"],"takeaways":["A pilot can support a next-step decision, not a long-term performance claim.","Record ticket selection, reviewer identity, and buyer-side support so bias is visible.","Use finished tickets and rework as the denominator instead of commit counts.","Keep access and customer data inside the minimum evidence boundary.","Write the pass, conditional pass, and stop rules before the first ticket."],"faqs":[{"question":"Can a two-week pilot predict long-term performance?","answer":"No. It can show how one developer handled a small set of work under specific conditions. Long-term claims need a longer window and more variety in the work."},{"question":"What if the pilot fails because of the buyer team?","answer":"Record the environmental cause and fix it before judging the developer. Missing tickets, access, or decisions are delivery findings in their own right."},{"question":"How many tickets are enough?","answer":"Two or three bounded tickets usually provide a reviewable sample. More tickets can add variety, but only if each one can still be reviewed with care."}],"related":[{"title":"Run a two-week offshore developer pilot with written exit criteria","href":"/blog/developeroffshore-run-a-two-week-offshore-developer-pilot-with-exit-criteria"},{"title":"Ticket readiness as an early delivery signal","href":"/research/developeroffshore-ticket-readiness-delivery-signal"}],"nextAction":{"heading":"Prepare a pilot decision brief","body":"Write the pilot question, the ticket set, the reviewer, and the three exit outcomes before access is granted. Keep approval of the next stage with your delivery owner.","label":"Plan a bounded pilot","href":"/services","anchorId":"pilot-decision-brief"}},{"slug":"developeroffshore-ticket-readiness-delivery-signal","title":"Ticket readiness as an early delivery signal","excerpt":"A measurement approach for ticket readiness in offshore delivery, showing how missing outcomes, owners, and acceptance checks turn into waiting time before code is written.","published":"2026-11-07","updated":"2026-11-07","sections":[{"heading":"Question and scope","body":["This analysis asks whether ticket readiness can give a buyer team an early signal of delivery delay. The population is tickets assigned to a development pod during a declared window. The unit is one ticket with its original brief, its first assignment, and the date it reached a reviewable change. Tickets that never entered development are still relevant because they can reveal a queue that looks active but cannot start.","The claim is limited to the relationship between recorded readiness and recorded waiting. It does not estimate a universal cost of a vague ticket or rank the people who wrote the brief. The useful question is local: in this backlog, which missing fields predict a ticket returning for information or sitting idle? A team can answer that question with a small, honest sample."]},{"heading":"Define readiness before measurement","body":["A ticket is ready when a developer can start without asking the buyer for a missing decision. That usually requires a user-visible outcome, the current behavior, the system boundary, acceptance checks, and a named reviewer. It also needs any dependency that must exist before the first change, such as credentials or a design approval. Readiness is a state the team defines, not a feeling the assignee has on Monday.","Write the definition down and use the same fields for every ticket in the sample. Keep the list short enough that people apply it consistently. If a field is optional, say when it becomes required. A definition that changes halfway through the window turns the comparison into a story about the people in the room."]},{"heading":"The queue as a population","body":["Build the population from the ticket system rather than from the tickets that happened to finish. Include tickets that were reopened, transferred to another owner, or closed without a code change. A queue that excludes the difficult items will look ready and fast at the same time. Report the eligible count and the number that entered development during the window.","Keep a stable key for each ticket across the board, the repository, and the release record. A transferred ticket must not appear twice just because it changed teams. Record the original brief and the later edits so the reviewer can see whether readiness improved after assignment. The history is part of the evidence, especially when the original ticket was thin."]},{"heading":"Waiting states and blocked time","body":["Measure the time a ticket spends waiting for a decision, access, or an environment, and keep those causes separate. A ticket blocked on a buyer answer is a different delivery problem from one blocked on a broken build. Combining them hides the action that would help. Ask the pod to record the waiting state when it begins, not reconstruct it from memory at the end.","Use the same clock and time zone for every duration. Store timestamps in UTC and translate only for display, so a distributed team does not create artificial gaps. Report the longest wait beside the median because one stuck ticket can reveal a process problem that an average conceals. Small samples need plain counts more than polished percentages."]},{"heading":"Rework and missing information","body":["Track how often a ticket returns to the author for missing information and how often a pull request returns for an avoidable defect. These are different forms of rework and should not be merged into a single quality score. A readiness gap usually appears as a question before code, while an implementation gap appears as review comments. The first is cheaper to fix and easier to prevent.","For each return, record the missing field or the failed check. Look for repetition across tickets rather than blaming one author. If acceptance checks are consistently vague, the problem sits in the brief template or the review habit. If access is consistently late, the problem sits in the onboarding path. The pattern points to the control that needs repair."]},{"heading":"Sampling and adverse cases","body":["Use a consecutive or systematic sample from the declared window and include at least one ticket that was blocked, one that was reopened, and one that never started. These adverse cases are where readiness problems become visible. A sample of only completed tickets will overstate how smoothly the queue works. Keep the inclusion rule fixed before collection begins.","Ask a second reviewer to classify one or two tickets using the same definition. Compare the classification and discuss disagreements with the ticket owner. A disagreement often reveals a field that the definition does not describe well. Update the definition for the next window, but do not rewrite the current sample as if the change had always applied."]},{"heading":"Ownership and privacy","body":["The buyer owner remains responsible for priority, acceptance, and any decision that changes customer behavior. The pod can record readiness gaps and propose a clearer brief, but it should not invent a requirement to make a ticket look ready. A developer who fills a missing outcome with a guess creates rework that the record may not capture. Escalate the gap instead of smoothing it over.","Keep customer and personal information out of the measurement file. Use synthetic examples and ticket identifiers rather than pasted customer messages. Limit access to the people who need the evidence and remove temporary access when the review closes. A readiness study does not require a copy of every conversation in the ticket, and a smaller record is easier to protect."]},{"heading":"Using readiness to improve the brief template","body":["A readiness review is most useful when it changes the template people use every day. If tickets repeatedly lack an acceptance check, add a required field with a short example. If the owner is often missing, make the owner part of the planning definition rather than a note added later. The change should reduce a specific question the pod had to ask, not add a form that nobody reads.","Test the revised template on a small set of new tickets before rolling it out. Compare the questions raised and the waiting time with the previous window. If the change does not help, remove it rather than keeping a field that creates work without evidence. A template earns its place by making the next ticket easier to start and review."]},{"heading":"What a readiness signal should not be used for","body":["Readiness data should not become a score for the person who wrote the ticket. A thin brief may reflect a new product owner, a missing decision from another team, or a template that never asked for the right information. Using the measure to rank authors discourages honest recording and makes the next window less reliable. The signal belongs to the process, not to an individual's reputation.","It should not be used to justify starting work without a decision either. A ticket can be marked ready only when the developer can act, not when the team is tired of waiting. If a decision is genuinely optional, say so and record the assumption. A readiness check that pressures people to declare readiness defeats its purpose."]},{"heading":"Reading the signal beside review time","body":["A readiness signal is more useful when it is read beside review time and rework. A ticket can be ready and still wait for a reviewer, or be thin and still pass because the reviewer fills the gap. Looking at both prevents the team from blaming the brief for a queue caused by review capacity. The two signals together point to the next action more reliably than either one alone.","Report the readiness gap and the review wait in the same weekly view. Ask whether the missing information caused a wait before development or a return after review. The answer tells the buyer whether to fix the intake or the review path. Keep the definitions stable so the comparison means something from one week to the next, even when the ticket mix changes."]},{"heading":"Limits and next step","body":["The finding is local to the window, the ticket mix, and the team's definition of ready. A change in the product area or the reviewer group can change the pattern. Test the conclusion with a second window before turning it into a rule. If the signal holds, use it to improve the brief template or the planning conversation rather than to rank authors.","Name the decision that depends on the result. A team might decide to add a readiness check before tickets enter the sprint, or to reserve review time for tickets that touch shared contracts. Record the change, the owner, and the next review date. The value of the measure is the improvement it prompts, not the number itself."]}],"sources":[{"name":"NIST Secure Software Development Framework","url":"https://csrc.nist.gov/projects/ssdf"},{"name":"CISA Cybersecurity Performance Goals","url":"https://www.cisa.gov/cybersecurity-performance-goals"},{"name":"U.S. Bureau of Labor Statistics, Software Developers","url":"https://www.bls.gov/ooh/computer-and-information-technology/software-developers.htm"}],"keyStats":["1 readiness definition per window","5 fields in a minimal ready ticket","3 waiting causes: decision, access, environment","2 adverse cases: reopened and never-started tickets"],"takeaways":["Define readiness as the state in which a developer can start without a buyer decision.","Include blocked, reopened, and never-started tickets in the population.","Separate waits for decisions, access, and environments before drawing conclusions.","Use missing fields and failed checks to locate the control that needs repair.","Treat the finding as local until a second window confirms the pattern."],"faqs":[{"question":"Is ticket readiness a performance metric for developers?","answer":"No. It describes the condition of the work entering the pod. It can reveal a buyer-side gap or a template problem, not the effort of an individual developer."},{"question":"How many tickets are needed for a useful sample?","answer":"A small consecutive sample can reveal a repeated missing field. The important requirement is to include the difficult cases and keep the inclusion rule fixed."},{"question":"What should happen when a ticket is not ready?","answer":"Record the missing decision, name the owner, and keep the ticket out of active development until the gap is resolved. Starting early usually moves the wait into review."}],"related":[{"title":"Turn a vague ticket into an offshore-ready work brief","href":"/blog/developeroffshore-turn-a-vague-ticket-into-an-offshore-ready-work-brief"},{"title":"What a two-week offshore developer pilot can and cannot prove","href":"/research/developeroffshore-what-a-two-week-offshore-pilot-can-prove"}],"nextAction":{"heading":"Prepare a readiness review","body":"Use a fixed definition, a bounded ticket sample, and one owner for each missing decision. Ask the pod to record waiting causes before the first change, not after the sprint.","label":"Plan a readiness review","href":"/services","anchorId":"readiness-review"}},{"slug":"developeroffshore-estimating-throughput-without-activity-metrics","title":"Estimating delivery throughput without activity metrics","excerpt":"How an offshore delivery pod can estimate throughput from finished work, waiting time, and review capacity without turning commits or messages into a performance score.","published":"2026-11-07","updated":"2026-11-07","sections":[{"heading":"Question and scope","body":["This analysis asks how a small offshore delivery pod can estimate throughput without using activity counts as a proxy for useful work. The unit is one finished, accepted change tied to a ticket and a review record. The window is a fixed number of working weeks with the same team and a comparable ticket mix. Estimates about future delivery are bounded by that window and should be revised when the mix changes.","The purpose is planning, not ranking. A throughput estimate helps a buyer decide how much work to start, when to add review capacity, and which commitments are unrealistic. It does not measure effort, loyalty, or the value of an individual. The record should make that distinction explicit so a manager does not reuse it as a performance score."]},{"heading":"Why activity counts mislead","body":["Commits, messages, and online hours rise when work is fragmented and fall when people take time to think. A developer debugging a difficult production issue may produce little visible activity for a day and still prevent a larger failure. A developer splitting one change into ten commits can look busier without finishing more work. The metric reflects tool behavior more than delivery.","Activity counts also reward the wrong response to a bottleneck. If review is slow, a team can start more work and generate more commits while finished output stays flat. The resulting dashboard looks productive while the queue of unfinished changes grows. Throughput measures the end of the process, where the buyer actually receives a result and can decide what to do next."]},{"heading":"Choose a unit of finished work","body":["Use a unit the team can count consistently, such as a ticket that passed its acceptance checks and was accepted by the named owner. A merged pull request is not enough if the change still waits for a release check or a customer decision. A released change is not enough if it was rolled back for a reason the review missed. Define the finish line once and keep it stable.","Some work does not fit the unit neatly, including incidents, dependency upgrades, and exploratory tasks. Record those in a separate category rather than forcing them into the ticket count. The aim is a comparable measure for the planned work, not a total that hides everything else. State what was excluded and why so the estimate is not read as a complete account."]},{"heading":"Measure waiting, not just working","body":["For each finished item, record the time it spent waiting for a reviewer, a decision, or an environment. The sum of those waits often explains more about delivery than the time spent coding. A pod can look slow because one approval arrives two days late every week. Waiting time gives the buyer a concrete lever that does not require pushing developers harder.","Keep waiting categories separate and report the largest one first. If review is the main wait, adding development capacity will make the queue worse. If a buyer decision is the main wait, the fix belongs with the buyer owner. The estimate should point to the constraint rather than imply that every hour is interchangeable or that every delay has the same cause."]},{"heading":"Review capacity as a constraint","body":["A small pod can only finish what its reviewers can check with care. Estimate review capacity from the number of changes a reviewer can handle in a normal week, then compare it with the arrival rate of new work. A team that starts work faster than it can review creates a hidden inventory of unfinished changes. The inventory consumes attention even when nobody is coding.","Protect review time in the calendar and treat it as delivery work rather than a favor. Track how often reviews are delayed because the reviewer is in meetings or on support duty. If the same person reviews every shared-contract change, that person is a single point of failure. The throughput estimate should show the constraint plainly enough for the buyer to act on it."]},{"heading":"Evidence from a bounded window","body":["Collect the eligible ticket set, the accepted count, the review wait, and the rework count for the window. Use the same source systems and the same definitions throughout. Report raw counts beside any rate so a small sample cannot look more certain than it is. A window with three finished items supports a planning conversation, not a forecast with decimal precision.","Include one adverse case, such as a ticket that was blocked for most of the window or a change that returned twice for review. Explain how the case affected the count rather than removing it as an outlier. Outliers often reveal the constraint the team most needs to fix. Keep the exclusion rule fixed before the window closes."]},{"heading":"What the numbers cannot say","body":["A throughput estimate cannot prove that a developer is productive, honest, or a good fit for the team. It cannot compare two people fairly when they worked on different systems with different review support. It also cannot predict a week with a major incident or a new product direction. Those changes require a new estimate, not a reinterpretation of the old one.","The estimate is also vulnerable to changes in ticket size. A team can raise its finished count by splitting work into smaller pieces, which may be useful or may hide a larger change that never lands. Pair the count with the acceptance evidence and the scope of the released work. A number without its unit and its boundary is easy to misread, especially when it travels into a planning meeting without the table behind it."]},{"heading":"Building a simple evidence table","body":["A table with one row per accepted item is enough for most small teams. Include the ticket, the finish date, the review wait, the decision wait, and whether the change returned for rework. Add a short note for any item that does not fit the normal path, including the reason it was excluded. The table should be small enough to inspect and specific enough to answer a question about one week without opening five other systems.","Keep the evidence table separate from the performance review system. A planning record should not follow a developer into an annual assessment without context. Restrict access to the people who need it and remove temporary copies when the window closes. Clear boundaries make it easier for the team to record problems honestly, including the weeks when the plan was wrong."]},{"heading":"Reviewing the estimate with the buyer","body":["Bring the estimate to the buyer with the constraint and one decision to make. For example, show that review wait is rising and ask whether to pause new work or add a reviewer for a specific area. Do not present a finished number without the assumptions behind it. The buyer needs to see what would change the result before committing to a plan.","Record the decision and the next review date in the same note as the estimate. If the buyer chooses to keep starting work, record the expected queue growth and the risk to the commitment. If the buyer chooses to pause, name the work that will wait. A planning conversation is useful when it ends with a tradeoff, not a request for more effort."]},{"heading":"When the estimate becomes a commitment","body":["A commitment needs more than a throughput estimate because it also carries a date, a scope, and a consequence for the buyer. Use the estimate to describe a range and the conditions that would move the work inside it. State which constraint must hold for the date to remain possible. If the constraint changes, revisit the date instead of treating the original estimate as a promise."]},{"heading":"A practical reporting routine","body":["Publish a short weekly view with four lines: accepted items, items waiting for review, items waiting for a buyer decision, and items returned for rework. Add one sentence about the constraint the team observed. Keep the definitions and the source links beside the numbers. The view should take minutes to read and should lead to one decision or one follow-up.","Review the estimate at the end of the window and write down what changed. If the constraint moved from review to access, adjust the plan and the owner. If the numbers do not match the lived experience, inspect the unit and the finish line before doubting the team. A planning measure is useful when it helps people make a better commitment, not when it settles an argument about effort."]}],"sources":[{"name":"U.S. Bureau of Labor Statistics, Software Developers","url":"https://www.bls.gov/ooh/computer-and-information-technology/software-developers.htm"},{"name":"NIST Cybersecurity Framework 2.0","url":"https://www.nist.gov/cyberframework"},{"name":"CISA Cyber Essentials","url":"https://www.cisa.gov/resources-tools/resources/cyber-essentials-toolkit"}],"keyStats":["1 finish line per estimate","4 weekly signals: accepted, review wait, decision wait, rework","0 activity counts used as a performance score","1 named constraint to act on each week"],"takeaways":["Count accepted work at the finish line, not commits or messages.","Report review and decision waits separately from coding time.","Treat reviewer capacity as the constraint it usually is.","Keep the unit and exclusion rule stable across the window.","Use the estimate for planning, never as an individual performance score."],"faqs":[{"question":"Can throughput estimates compare two offshore developers?","answer":"Not fairly when they work on different systems with different review support. Use the estimate for capacity planning and keep individual evaluation tied to the work and its context."},{"question":"What counts as accepted work?","answer":"A ticket that passed its agreed acceptance checks and was accepted by the named owner. Merge alone may not be enough if release checks or a customer decision still remain."},{"question":"How often should the estimate be updated?","answer":"Review it at the end of each fixed window and whenever the team, ticket mix, or review capacity changes. Do not adjust it weekly to make a commitment look better."}],"related":[{"title":"Decision latency in offshore software delivery","href":"/research/developeroffshore-decision-latency-in-offshore-delivery"},{"title":"Set a work-in-progress limit for a shared offshore backlog","href":"/blog/developeroffshore-set-a-work-in-progress-limit-for-a-shared-offshore-backlog"}],"nextAction":{"heading":"Prepare a throughput review","body":"Define the finish line, collect accepted work and waiting causes for a fixed window, and name the constraint your team will act on. Keep release approval with your own owner.","label":"Plan a throughput review","href":"/services","anchorId":"throughput-review"}},{"slug":"developeroffshore-decision-latency-in-offshore-delivery","title":"Decision latency in offshore software delivery","excerpt":"An analysis of waiting on buyer decisions in offshore delivery: how one unanswered question becomes a queue, how to record the wait, and how to escalate without moving authority.","published":"2026-11-07","updated":"2026-11-07","sections":[{"heading":"Question and scope","body":["This analysis asks how decision latency affects an offshore development pod when the buyer team holds authority over priorities, contracts, access, and release risk. The unit is one recorded decision request with an owner and a date. The window is a normal delivery period with ordinary planning and review work. The report does not treat every delay as a failure because some decisions need evidence that takes time to produce.","Decision latency is the time between a request that is clear enough to answer and the recorded answer. It is not the same as the time spent discussing a problem before anyone knows what to ask. The distinction matters because a pod can waste days on an unclear request or wait on a clear one that nobody owns. The first is a briefing problem, while the second is an authority and capacity problem."]},{"heading":"How a decision becomes late","body":["A decision becomes late when the request reaches someone who cannot answer it, lacks the evidence to answer it, or does not know that the pod is waiting. Each cause needs a different response. Forwarding the request to a larger group may feel like action while making the answer less likely. The pod should record the owner and the evidence needed before it escalates.","Another common cause is a request that hides two decisions inside one question. A ticket may ask whether to change a public response and whether to notify customers, which may belong to different owners. Split the question before assigning it. A clear request with one owner is easier to answer and easier to audit later."]},{"heading":"One owner and one recorded question","body":["Every decision request should name one accountable owner, even when several people must be consulted. The owner can gather input, but the record should show who made the call. Write the question in plain language, the options considered, the recommendation, and the consequence of waiting. A short request is more likely to receive a timely answer than a long narrative with the question buried at the end.","Record the request in the same system as the work it affects. A chat message that disappears is not a decision record. Link the answer to the ticket and state whether it changes scope, sequence, or risk. If the owner is unavailable, name an alternate with the same authority rather than asking the pod to guess."]},{"heading":"Waiting time as a delivery cost","body":["Waiting time consumes capacity even when nobody is working on the blocked ticket. The pod may switch to another item, but the original work still needs attention and the context must be rebuilt later. Frequent switching adds review and coordination cost that a simple blocked-hours count may miss. The buyer should see the wait as part of the delivery system, not as idle time that can be absorbed for free.","Measure the wait from the moment the request is clear to the moment the answer is recorded. Keep the clock in UTC and separate waiting for a decision from waiting for access or an environment. Report the oldest open request and the number that have crossed the agreed threshold. A single stuck decision can delay several tickets and distort the weekly plan."]},{"heading":"Escalation without bypassing authority","body":["Escalation should raise visibility, not transfer the decision to whoever is most available. If the named owner has not answered by the agreed date, notify that person and their manager with the request, the impact, and the options. Ask for a decision or a new owner. Do not let the pod approve a contract change or an access exception because waiting feels expensive.","Set a threshold that reflects the cost of the wait. A routine copy change may wait a day, while a release blocker may need same-day attention. The threshold belongs in the working agreement and should be reviewed when the cadence changes. Escalation is a defined path with a record, not an informal appeal to the loudest person in the channel."]},{"heading":"Evidence for a decision review","body":["A decision review needs the request, the owner, the date, the answer, and the work affected. It should also show whether the answer changed later and why. A decision that was reversed may still be a good decision if the new evidence justified it. The record should make that reasoning visible instead of presenting every change as a mistake.","Sample a small set of decisions across the window and include one that waited too long. Ask the owner and the pod to identify the cause without turning the review into a blame session. The useful output is a change to the request template, the owner list, or the escalation path. A decision review that produces only a chart has not finished the work."]},{"heading":"Risks of centralizing decisions","body":["A buyer team may centralize decisions to keep control, which can be appropriate for contracts, security, and customer commitments. The risk is that routine choices also queue behind the same person. A pod that must ask for permission to rename a variable or adjust a test will not deliver at a useful pace. Write down which decisions are routine and which require the owner.","Delegation should come with a boundary and a review path. A developer can choose an implementation detail inside an accepted design, but should not change the public behavior without approval. The boundary should be specific enough that a reviewer can tell whether it was crossed. Centralization is a cost, and the team should pay it only where the risk justifies the delay."]},{"heading":"Recording decisions so a later reader can follow","body":["A decision record should let a reader who was not in the room understand what was decided and why. State the question, the owner, the options, the evidence, the answer, and the date. Add the consequence for scope, sequence, or risk and link the affected tickets. A short record written at the time is more reliable than a polished summary created after the release.","Keep the record in a searchable place and link it from the work it changed. Do not rewrite old decisions when the answer changes; add a new entry that references the earlier one. This habit preserves the reasoning and prevents a team from repeating a debate it already settled. It also shows new members how authority works in practice."]},{"heading":"What a decision review should change","body":["A decision review should produce a change to a request template, an owner list, a meeting cadence, or an escalation path. If the review produces only a description of the delay, the team has learned little that will alter the next week. Choose one change that addresses the most common cause and give it an owner. Review the effect after a short window.","Avoid changes that simply ask people to respond faster without removing the cause. A missing piece of evidence will still be missing tomorrow, and an owner who lacks authority will still forward the question. The review should make the next decision easier to answer, not just make the wait more visible. Visibility is the starting point, while a changed path is the result."]},{"heading":"A weekly review of the oldest request","body":["Put the oldest open decision on the weekly delivery agenda and read its history aloud. State the question, the owner, the date it was asked, and the evidence still missing. Ask whether the request is clear and whether the owner has the authority to answer it. The review should produce an answer, a new owner, or a smaller question that can be answered now.","Do not let the oldest item become a ritual that is discussed and carried forward again. If the owner cannot act, escalate with the impact and a proposed date. If the question is no longer relevant, close it and record why. The agenda item is useful only when it changes the state of the request."]},{"heading":"Limits and next step","body":["The analysis describes waiting inside one delivery system and should not be generalized to every team or decision type. Some delays are caused by incomplete evidence, conflicting priorities, or legal review that cannot be shortened by better process. Others reflect a real tradeoff that deserves time. The point is to make the wait visible and assign the right owner, not to demand instant answers for every question.","Choose one change for the next window, such as a decision request template or a weekly review of the oldest waiting item. Give the change an owner and a review date. If the wait does not improve, inspect whether the owner has the authority and the evidence to decide. A faster answer is useful only when it is also the right answer."]}],"sources":[{"name":"NIST SP 800-53 Rev. 5, Security and Privacy Controls","url":"https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"},{"name":"NIST Cybersecurity Framework 2.0","url":"https://www.nist.gov/cyberframework"},{"name":"International Labour Organization, Non-standard employment","url":"https://www.ilo.org/global/topics/non-standard-employment/WCMS_534825/lang--en/index.htm"}],"keyStats":["1 accountable owner per decision","2 clocks: request clear to answer, answer to work resumed","3 causes: wrong owner, missing evidence, unclear question","1 oldest waiting item reviewed each week"],"takeaways":["Define the request as clear before starting the latency clock.","Give every decision one accountable owner and one recorded question.","Separate decision wait from access and environment wait.","Escalate with impact and options, not by reassigning authority informally.","Delegate routine choices explicitly so only real risk queues at the top."],"faqs":[{"question":"What counts as decision latency?","answer":"The time from a clear, owned request to a recorded answer. Time spent clarifying an unclear request is a briefing problem and should be measured separately."},{"question":"Should the pod ever make the decision itself?","answer":"Only within a documented boundary. Routine implementation choices can sit with the developer, while contract, security, access, and customer-impact decisions stay with the named owner."},{"question":"How do we reduce waiting without adding pressure?","answer":"Clarify the request, name one owner, provide the evidence they need, and review the oldest item weekly. Some waits are legitimate and should be planned rather than rushed."}],"related":[{"title":"Run a weekly delivery review for a distributed pod","href":"/blog/developeroffshore-run-a-weekly-delivery-review-for-a-distributed-pod"},{"title":"What a two-week offshore developer pilot can and cannot prove","href":"/research/developeroffshore-what-a-two-week-offshore-pilot-can-prove"}],"nextAction":{"heading":"Prepare a decision-latency review","body":"Record clear requests, owners, and answers for one bounded window, then review the oldest waiting item. Keep contract and release authority with your own owner.","label":"Plan a decision review","href":"/services","anchorId":"decision-latency-review"}},{"slug":"developeroffshore-knowledge-transfer-risk-developer-departure","title":"Knowledge-transfer risk when a developer leaves a distributed team","excerpt":"A risk analysis of developer departures in distributed teams: single-owner knowledge, tested handoffs, access removal, and the evidence that a transfer actually happened.","published":"2026-11-07","updated":"2026-11-07","sections":[{"heading":"Question and scope","body":["This analysis asks what a distributed engineering team loses when one developer leaves and how the team can tell whether the knowledge moved before access changed. The unit is one departure with a defined set of owned systems, decisions, and operational routines. The window runs from notice to the first review after access removal. The report focuses on continuity risk rather than the reasons for the departure.","Knowledge transfer is not a farewell meeting or a folder of notes. It is the successful movement of enough context for another person to run the work, make routine decisions, and recognize when to escalate. The risk is highest where one person holds both the technical detail and the relationships needed to act. A team should look for those pockets before the last week."]},{"heading":"Find the work with a single owner","body":["Start with the systems, jobs, scripts, and approvals that only one person has operated. Include the manual steps that never made it into a runbook, the vendor contact who answers only to one name, and the query used to verify a migration. Check recent pull requests, alert acknowledgements, and release records for repeated names. A map built only from a repository ownership file will miss the operational knowledge.","Ask the departing developer to mark each item as documented and tested, documented but untested, or known only to them. The last group is the transfer list. Confirm it with a second person who has worked nearby, because people often underestimate what they know. A short verified list is more useful than a long inventory that nobody has checked."]},{"heading":"Documentation is not transfer","body":["A document can describe a procedure without proving that another person can execute it. Transfer requires a reader, a clean environment, and a result that matches the expected output. The note should include the command, the common failure, the recovery step, and the person to contact when the failure is unfamiliar. It should not contain the secret itself, only the approved path to obtain it.","Test each critical note with someone who did not write it and who will own the work afterward. Fix the gaps while the author can still answer questions. Record the test date and the result beside the note. An untested document is a claim about knowledge, while a tested procedure is evidence that some of it moved."]},{"heading":"Test the handoff with a real task","body":["Choose one representative task that the new owner will perform without the departing developer. Use a real ticket with a safe scope, such as a routine release check or a small configuration change. Watch where the new owner hesitates and update the note at that point. The rehearsal should include the decision points, not only the happy path.","Record the questions raised, the remaining risk, and the person who will answer future questions. If the task cannot be completed without the departing developer, the transfer is incomplete. Schedule a second rehearsal for the gaps that matter to production. The goal is a demonstrated handoff that another person can repeat, not a signed checklist with no evidence behind it."]},{"heading":"Access removal and continuity","body":["Remove access after the ownership transfer is verified, not before the new owner can act. Update the repository role, deployment permission, vendor account, and alert routing while the departing developer can still confirm the change. Check that the new owner can complete the action rather than only appearing in a directory. A name on a list is not the same as working access.","Keep a short overlap for questions that appear after the first real task, with a named contact and an end date. Do not keep a shared account open as a convenience. If a former contributor must be contacted after the overlap, treat that as a knowledge gap with an owner and a follow-up action. The boundary should be clean enough to audit."]},{"heading":"Evidence of a completed transfer","body":["A completed transfer has a named owner for each critical area, a tested note or runbook, a rehearsal result, and a record of access changes. It also has a list of open questions and the person responsible for answering them. The evidence should be specific enough that a manager who was not involved can see what was checked. A general statement that the handoff went well is not enough.","Review the transfer two weeks after the departure and ask the new owner what took longer than expected. Update the notes and close the gaps that appeared in real work. If the team still depends on the former contributor for routine tasks, record the dependency as an open risk. The review is the point where the team learns whether the transfer survived contact with the work."]},{"heading":"Fair treatment and privacy","body":["A departure plan should respect the person leaving as well as the team that remains. Ask for knowledge transfer within the notice period and avoid requesting unpaid work after the final day. Keep personal information out of the transfer record and share only the technical context another person needs. A rushed or punitive process makes future employees less likely to document what they know.","The departing developer should know which notes will be shared, who will own them, and when access will end. Give them a chance to correct an inaccurate record before the handoff closes. This is fair to the person and useful to the team because corrections are easier while the context is fresh. A transfer process that ignores the human side often produces worse evidence."]},{"heading":"Cross-training as a standing control","body":["A team can reduce departure risk by making cross-training part of normal work rather than a response to notice. Ask a second person to review a runbook, shadow a release, or take the first pass on a recurring task. Rotate the on-call contact for one low-risk service when the team is ready. These small exercises create familiarity before it is urgently needed.","Cross-training should not become a second full-time job for the person who already owns the area. Protect the time and treat the exercise as delivery work with an outcome. Record what was tested, what remains single-owner, and when the next practice will happen. A standing habit is more reliable than a rushed transfer during a notice period."]},{"heading":"Writing the transfer record","body":["A transfer record should list the critical areas, the new owner, the evidence of a tested handoff, and the open questions. Include the access changes and the date they were verified. Keep it short enough to review and specific enough to audit. The record is not a narrative of the departure; it is the proof that the work can continue.","Store the record with the team runbook and link it from the relevant services. Review it when a role changes or a new person joins the on-call rotation. If an area still has one owner, mark that as a risk rather than hiding it in a general statement. The record should make the next transfer easier, not just document this one."]},{"heading":"The first week after departure","body":["The first week after access removal is the real test of a transfer. Ask the new owner to run one routine check without contacting the former developer and record the result. If a question comes up, send it to the named contact rather than reopening a private channel. Review the result at the end of the week and update the runbook where the new owner had to improvise."]},{"heading":"Limits and next step","body":["No transfer can preserve every piece of context, and some loss is normal when a person leaves. The analysis cannot tell a team how much risk is acceptable or how much notice every departure will provide. It can show where single-owner knowledge sits and whether the team tested the handoff. Those facts support a bounded decision about what to fix first.","Choose one critical area for the next transfer drill and run it before the next departure. Record the result, the gaps, and the owner of each fix. Use the same method when a role changes or a contractor rotates, and keep the record beside the runbook. Continuity improves through small rehearsals, not through a document written in the final week."]}],"sources":[{"name":"NIST SP 800-53 Rev. 5, Security and Privacy Controls","url":"https://csrc.nist.gov/pubs/sp/800/53/r5/upd1/final"},{"name":"CISA Zero Trust Maturity Model","url":"https://www.cisa.gov/zero-trust-maturity-model"},{"name":"International Labour Organization, Non-standard employment","url":"https://www.ilo.org/global/topics/non-standard-employment/WCMS_534825/lang--en/index.htm"}],"keyStats":["1 named owner per critical area after departure","3 knowledge states: tested, documented, single-owner","1 rehearsal task before access removal","2 weeks after departure for a continuity review"],"takeaways":["Map single-owner work from operations, not only from repository ownership files.","Treat a tested procedure as the evidence of transfer, not an untested note.","Rehearse the handoff with a real task before access changes.","Move ownership before removing access so the receiver can act.","Review continuity two weeks later and record remaining dependencies."],"faqs":[{"question":"How early should a knowledge transfer start?","answer":"As soon as a departure or role change is known. Prioritize production paths and single-owner work first, then use the remaining time for notes and rehearsal."},{"question":"Is documentation enough for a handoff?","answer":"No. A document becomes evidence only when another person has followed it and reached the expected result. Test the critical notes with the future owner."},{"question":"When should access be removed?","answer":"After the receiver can perform the critical actions and the transfer record is verified. Keep only the access needed for the agreed overlap, and remove it on the recorded end date."}],"related":[{"title":"Plan a knowledge transfer before an offshore developer leaves","href":"/blog/developeroffshore-plan-a-knowledge-transfer-before-an-offshore-developer-leaves"},{"title":"Decision latency in offshore software delivery","href":"/research/developeroffshore-decision-latency-in-offshore-delivery"}],"nextAction":{"heading":"Prepare a continuity drill","body":"Pick one critical area, name the future owner, and rehearse a real task before access changes. Keep production approval and access policy with your own team.","label":"Plan a continuity drill","href":"/services","anchorId":"continuity-drill"}}];
